  {μ : Measure Ω} [inst_2 : MeasurableSpace T] [inst_3 : MeasurableSingletonClass U] [inst_4 : IsFiniteMeasure μ]
  (hZ : Measurable Z) [inst_5 : Fintype U] : FiniteRange.toFinset Z ⊆ Finset.univ := by
  simp

